('GEN_ENG', 4, 'Unit 4: Formal, Informal & Professional Correspondence', 'Formal, Informal & Professional Correspondence', 'ඒකකය 04: ලිපි ලේඛන ලිවීම, විද්‍යුත් තැපැල් සහ නිල සන්නිවේදනය', 'அலகு 04: உத்தியோகபூர்வ, தனிப்பட்ட மற்றும் மின்னஞ்சல் கடிதங்கள்', '4.1', 'Formal letters: Applications, inquiries, complaints and requests with standard layout', 'Formal letters: Applications, inquiries, complaints and requests with standard layout', 'නිල ලිපි: රැකියා අයදුම්පත්, විමසීම්, පැමිණිලි සහ සම්මත සැකැස්ම', 'உத்தியோகபூர்வ கடிதங்கள்: தொழில் விண்ணப்பம், புகார்கள், வேண்டுகோள் கடிதங்கள்'),
('GEN_ENG', 4, 'Unit 4: Formal, Informal & Professional Correspondence', 'Formal, Informal & Professional Correspondence', 'ඒකකය 04: ලිපි ලේඛන ලිවීම, විද්‍යුත් තැපැල් සහ නිල සන්නිවේදනය', 'அலகு 04: உத்தியோகபூர்வ, தனிப்பட்ட மற்றும் மின்னஞ்சல் கடிதங்கள்', '4.2', 'Professional emails, business memos, notices and circular formatting', 'Professional emails, business memos, notices and circular formatting', 'වෘත්තීය ඊමේල්, ව්‍යාපාරික සටහන්, දැන්වීම් සහ චක්‍රලේඛ සැකසීම', 'தொழில்சார் மின்னஞ்சல்கள், குறிப்பாணைகள் (Memos) மற்றும் உத்தியோகபூர்வ அறிவித்தல்கள்'),
('GEN_ENG', 5, 'Unit 5: Report Writing, Summarization & Data Description', 'Report Writing, Summarization & Data Description', 'ඒකකය 05: වාර්තා ලිවීම, සාරාංශකරණය සහ ප්‍රස්ථාරික දත්ත විස්තර කිරීම', 'அலகு 05: அறிக்கை எழுதுதல், சுருக்கக் குறிப்பு மற்றும் வரைபட தரவு விபரிப்பு', '5.1', 'Writing descriptive reports on bar charts, pie charts, tables and process flow diagrams', 'Writing descriptive reports on bar charts, pie charts, tables and process flow diagrams', 'ප්‍රස්ථාර, වගු සහ ක්‍රියාවලි සටහන් විස්තර කරමින් තාක්ෂණික වාර්තා ලිවීම', 'வரைபடங்கள், அட்டவணைகள் மற்றும் படிமுறை வரைபடங்களை விபரித்து எழுதுதல்'),
('GEN_ENG', 5, 'Unit 5: Report Writing, Summarization & Data Description', 'Report Writing, Summarization & Data Description', 'ඒකකය 05: වාර්තා ලිවීම, සාරාංශකරණය සහ ප්‍රස්ථාරික දත්ත විස්තර කිරීම', 'அலகு 05: அறிக்கை எழுதுதல், சுருக்கக் குறிப்பு மற்றும் வரைபட தரவு விபரிப்பு', '5.2', 'Summarizing lengthy texts, identifying key topic sentences and avoiding plagiarism', 'Summarizing lengthy texts, identifying key topic sentences and avoiding plagiarism', 'දීර්ඝ පාඨ සාරාංශගත කිරීම, ප්‍රධාන මාතෘකා වාක්‍ය හඳුනාගැනීම සහ සංක්ෂිප්තය', 'நீண்ட கட்டுரைகளை சுருக்கி வரைதல் மற்றும் மூலக் கருத்துக்களைத் தொகுத்தல்'),
('GEN_ENG', 6, 'Unit 6: Essay Writing & Persuasive Composition', 'Essay Writing & Persuasive Composition', 'ඒකකය 06: රචනා ලිවීම සහ තාර්කික ප්‍රකාශනය', 'அலகு 06: கட்டுரை எழுதுதலும் தர்க்கரீதியான வாதமும்', '6.1', 'Essay structure: Thesis statement, body paragraphs, transitions and conclusion', 'Essay structure: Thesis statement, body paragraphs, transitions and conclusion', 'රචනා ව්‍යුහය: ප්‍රස්තුත ප්‍රකාශය, ඡේද ගොඩනැංවීම, සම්බන්ධක පද සහ සමාප්තිය', 'கட்டுரைக் கட்டமைப்பு: ஆரம்பக் கூற்று, உடற்பகுதிகள், இணைப்புச் சொற்கள், முடிவுரை'),
('GEN_ENG', 6, 'Unit 6: Essay Writing & Persuasive Composition', 'Essay Writing & Persuasive Composition', 'ඒකකය 06: රචනා ලිවීම සහ තාර්කික ප්‍රකාශනය', 'அலகு 06: கட்டுரை எழுதுதலும் தர்க்கரீதியான வாதமும்', '6.2', 'Argumentative, expository and discursive essays on contemporary global themes', 'Argumentative, expository and discursive essays on contemporary global themes', 'වාදනාත්මක, විග්‍රහාත්මක සහ සංවාදාත්මක රචනා ලිවීම', 'வாதக்கட்டுரைகள், விளக்கக் கட்டுரைகள் மற்றும் தற்கால சமூகப் பிரச்சினைகள்')
ON CONFLICT (subject, unit_number, sub_lesson_code) DO UPDATE SET
  unit_name = EXCLUDED.unit_name,
  unit_name_en = EXCLUDED.unit_name_en,
  unit_name_si = EXCLUDED.unit_name_si,
  unit_name_ta = EXCLUDED.unit_name_ta,
  sub_lesson_title = EXCLUDED.sub_lesson_title,
  sub_lesson_title_en = EXCLUDED.sub_lesson_title_en,
  sub_lesson_title_si = EXCLUDED.sub_lesson_title_si,
  sub_lesson_title_ta = EXCLUDED.sub_lesson_title_ta;

-- 2. Master canonical seed function covering all 37 Sri Lankan G.C.E. A/L subjects
CREATE OR REPLACE FUNCTION public.seed_user_syllabus_from_canonical(p_user_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $FUNC$
DECLARE
  v_sub RECORD;
  v_canon_sub TEXT;
  v_unit RECORD;
  v_unit_id UUID;
BEGIN
  FOR v_sub IN 
    SELECT s.id, s.name, s.code, s.slug 
    FROM public.subjects s
    WHERE s.user_id = p_user_id
  LOOP
    v_canon_sub := NULL;

    -- Common & Compulsory Subjects
    IF UPPER(v_sub.code) IN ('GEN_ENG', '13') OR v_sub.slug ILIKE '%general%eng%' OR v_sub.name ILIKE '%general english%' THEN
      v_canon_sub := 'GEN_ENG';
    ELSIF UPPER(v_sub.code) IN ('COMMON_TEST', '12') OR v_sub.slug ILIKE '%common%' OR v_sub.name ILIKE '%common general%' THEN
      v_canon_sub := 'COMMON_TEST';

    -- Physical Science / Maths Stream
    ELSIF UPPER(v_sub.code) IN ('COMB_MATH', '12', 'AL-004', 'SUBJ-004') 
       OR (v_sub.slug ILIKE '%math%' AND v_sub.slug NOT ILIKE '%high%') 
       OR v_sub.name ILIKE '%combined mathematics%' 
       OR (v_sub.name ILIKE '%mathematics%' AND v_sub.name NOT ILIKE '%higher%') THEN
      v_canon_sub := 'COMB_MATH';
    ELSIF UPPER(v_sub.code) IN ('HIGH_MATH', '13', 'AL-021', 'SUBJ-021') 
       OR v_sub.slug ILIKE '%high%math%' 
       OR v_sub.name ILIKE '%higher mathematics%' THEN
      v_canon_sub := 'HIGH_MATH';

    -- Biological Science Stream
    ELSIF UPPER(v_sub.code) IN ('BIO', '09', 'AL-001', 'SUBJ-001') OR v_sub.slug ILIKE '%bio%' OR v_sub.name ILIKE '%biology%' THEN
      v_canon_sub := 'BIO';
    ELSIF UPPER(v_sub.code) IN ('CHEM', '10', 'AL-002', 'SUBJ-002') OR v_sub.slug ILIKE '%chem%' OR v_sub.name ILIKE '%chemistry%' THEN
      v_canon_sub := 'CHEM';
    ELSIF UPPER(v_sub.code) IN ('PHYS', '01', 'AL-003', 'SUBJ-003') OR v_sub.slug ILIKE '%phys%' OR v_sub.name ILIKE '%physics%' THEN
      v_canon_sub := 'PHYS';
    ELSIF UPPER(v_sub.code) IN ('AGRI', '08', 'AL-006', 'SUBJ-006') OR v_sub.slug ILIKE '%agri%' OR v_sub.name ILIKE '%agri%' THEN
      v_canon_sub := 'AGRI';

    -- Technology Stream
    ELSIF UPPER(v_sub.code) IN ('ET', 'AL-007', 'SUBJ-007') OR v_sub.slug ILIKE '%et%' OR v_sub.name ILIKE '%engineering tech%' THEN
      v_canon_sub := 'ET';
    ELSIF UPPER(v_sub.code) IN ('SFT', 'AL-008', 'SUBJ-008') OR v_sub.slug ILIKE '%sft%' OR v_sub.name ILIKE '%science for tech%' THEN
      v_canon_sub := 'SFT';
    ELSIF UPPER(v_sub.code) IN ('ICT', '005', '20', 'AL-005', 'SUBJ-005') OR v_sub.slug ILIKE '%ict%' OR v_sub.name ILIKE '%information%' THEN
      v_canon_sub := 'ICT';
    ELSIF UPPER(v_sub.code) IN ('BST', '66', 'AL-025', 'SUBJ-025') OR v_sub.slug ILIKE '%bst%' OR v_sub.name ILIKE '%biosystem%' OR v_sub.name ILIKE '%food%' THEN
      v_canon_sub := 'BST';

    -- Commerce Stream
    ELSIF UPPER(v_sub.code) IN ('ACC', '21', 'AL-009', 'SUBJ-009') OR v_sub.slug ILIKE '%account%' OR v_sub.name ILIKE '%accounting%' THEN
      v_canon_sub := 'ACC';
    ELSIF UPPER(v_sub.code) IN ('BS', '23', 'AL-010', 'SUBJ-010') OR v_sub.slug ILIKE '%business%' OR v_sub.name ILIKE '%business studies%' THEN
      v_canon_sub := 'BS';
    ELSIF UPPER(v_sub.code) IN ('ECON', '22', 'AL-011', 'SUBJ-011') OR v_sub.slug ILIKE '%econ%' OR v_sub.name ILIKE '%economics%' THEN
      v_canon_sub := 'ECON';
    ELSIF UPPER(v_sub.code) IN ('STATS', '28', 'AL-020', 'SUBJ-020') OR v_sub.slug ILIKE '%stat%' OR v_sub.name ILIKE '%statistics%' THEN
      v_canon_sub := 'STATS';

    -- Languages & Literature
    ELSIF UPPER(v_sub.code) IN ('TAMIL_LIT', 'TAMIL', '32', '71') OR v_sub.slug ILIKE '%tamil%' OR v_sub.name ILIKE '%tamil%' THEN
      v_canon_sub := 'TAMIL_LIT';
    ELSIF UPPER(v_sub.code) IN ('SINHALA', '41', 'AL-015', 'SUBJ-015') OR v_sub.slug ILIKE '%sinhala%' OR v_sub.name ILIKE '%sinhala%' THEN
      v_canon_sub := 'SINHALA';
    ELSIF UPPER(v_sub.code) IN ('ENG_LIT', '46', '72') OR v_sub.slug ILIKE '%english%lit%' OR v_sub.name ILIKE '%english literature%' THEN
      v_canon_sub := 'ENG_LIT';

    -- Social Sciences & Humanities
    ELSIF UPPER(v_sub.code) IN ('HOME_ECON', '61') OR v_sub.slug ILIKE '%home%econ%' OR v_sub.name ILIKE '%home economics%' THEN
      v_canon_sub := 'HOME_ECON';
    ELSIF UPPER(v_sub.code) IN ('POL_SCI', '24', 'AL-012', 'SUBJ-012') OR v_sub.slug ILIKE '%pol%' OR v_sub.name ILIKE '%political%' THEN
      v_canon_sub := 'POL_SCI';
    ELSIF UPPER(v_sub.code) IN ('LOGIC', '25', 'AL-013', 'SUBJ-013') OR v_sub.slug ILIKE '%logic%' OR v_sub.name ILIKE '%logic%' THEN
      v_canon_sub := 'LOGIC';
    ELSIF UPPER(v_sub.code) IN ('GEO', 'GEOGRAPHY', '22', 'AL-014', 'SUBJ-014') OR v_sub.slug ILIKE '%geo%' OR v_sub.name ILIKE '%geography%' THEN
      v_canon_sub := 'GEO';
    ELSIF UPPER(v_sub.code) IN ('HIST', 'HISTORY', '26', 'AL-016', 'SUBJ-016') OR v_sub.slug ILIKE '%hist%' OR v_sub.name ILIKE '%history%' THEN
      v_canon_sub := 'HISTORY';
    ELSIF UPPER(v_sub.code) IN ('MEDIA', '29', 'AL-019', 'SUBJ-019') OR v_sub.slug ILIKE '%media%' OR v_sub.name ILIKE '%media%' OR v_sub.name ILIKE '%communication%' THEN
      v_canon_sub := 'MEDIA';

    -- Aesthetics (Dance, Music, Drama, Art)
    ELSIF UPPER(v_sub.code) IN ('DRAMA', '57', '60') OR v_sub.slug ILIKE '%drama%' OR v_sub.name ILIKE '%drama%' THEN
      v_canon_sub := 'DRAMA';
    ELSIF UPPER(v_sub.code) IN ('BHARATHA', '53') OR v_sub.slug ILIKE '%bharatha%' OR v_sub.name ILIKE '%bharatha%' THEN
      v_canon_sub := 'BHARATHA';
    ELSIF UPPER(v_sub.code) IN ('DANCE_INDIGENOUS', 'DANCE', '52') OR v_sub.slug ILIKE '%dance%' OR v_sub.name ILIKE '%dance%' OR v_sub.name ILIKE '%dancing%' THEN
      v_canon_sub := 'DANCE_INDIGENOUS';
    ELSIF UPPER(v_sub.code) IN ('MUSIC_CARNATIC', '55') OR v_sub.slug ILIKE '%carnatic%' OR v_sub.name ILIKE '%carnatic%' THEN
      v_canon_sub := 'MUSIC_CARNATIC';
    ELSIF UPPER(v_sub.code) IN ('MUSIC_WESTERN', '56') OR v_sub.slug ILIKE '%western%music%' OR v_sub.name ILIKE '%western music%' THEN
      v_canon_sub := 'MUSIC_WESTERN';
    ELSIF UPPER(v_sub.code) IN ('MUSIC_ORIENTAL', 'MUSIC', '54') OR v_sub.slug ILIKE '%music%' OR v_sub.name ILIKE '%music%' OR v_sub.name ILIKE '%oriental%' THEN
      v_canon_sub := 'MUSIC_ORIENTAL';
    ELSIF UPPER(v_sub.code) IN ('ART', '51', 'AL-018', 'SUBJ-018') OR v_sub.slug ILIKE '%art%' OR v_sub.name ILIKE '%art%' THEN
      v_canon_sub := 'ART';

    -- Religions & Civilizations
    ELSIF UPPER(v_sub.code) IN ('BUDDHIST_CULTURE', '43', 'AL-017', 'SUBJ-017') OR v_sub.slug ILIKE '%buddhist%culture%' OR v_sub.name ILIKE '%buddhist culture%' OR v_sub.name ILIKE '%buddhist civilization%' THEN
      v_canon_sub := 'BUDDHIST_CULTURE';
    ELSIF UPPER(v_sub.code) IN ('BUDDHISM', '42') OR v_sub.slug ILIKE '%buddhism%' OR v_sub.name ILIKE '%buddhism%' THEN
      v_canon_sub := 'BUDDHISM';
    ELSIF UPPER(v_sub.code) IN ('HINDUISM', '44', '46') OR v_sub.slug ILIKE '%hindu%' OR v_sub.name ILIKE '%hindu%' THEN
      v_canon_sub := 'HINDUISM';
    ELSIF UPPER(v_sub.code) IN ('ISLAM', '48', '47') OR v_sub.slug ILIKE '%islam%' OR v_sub.name ILIKE '%islam%' THEN
      v_canon_sub := 'ISLAM';
    ELSIF UPPER(v_sub.code) IN ('CHRISTIANITY', '49') OR v_sub.slug ILIKE '%christ%' OR v_sub.name ILIKE '%christ%' THEN
      v_canon_sub := 'CHRISTIANITY';

    ELSE
      -- Fallback to exact match with code or slug
      SELECT subject INTO v_canon_sub FROM public.canonical_syllabus 
      WHERE UPPER(subject) = UPPER(v_sub.code) OR UPPER(subject) = UPPER(v_sub.slug) 
      LIMIT 1;
    END IF;

    IF v_canon_sub IS NOT NULL THEN
      -- Delete existing units and subunits for this subject
      DELETE FROM public.syllabus_units WHERE subject_id = v_sub.id;

      -- Insert units from canonical_syllabus
      FOR v_unit IN 
        SELECT DISTINCT unit_number, 
               COALESCE(unit_name_en, regexp_replace(unit_name, '^ඒකකය\s*\d+\s*:\s*', '')) AS u_title,
               COALESCE(unit_name_si, unit_name) AS u_si,
               unit_name_ta AS u_ta
        FROM public.canonical_syllabus 
        WHERE subject = v_canon_sub
        ORDER BY unit_number
      LOOP
        INSERT INTO public.syllabus_units (subject_id, unit_number, title, sinhala_title, tamil_title)
        VALUES (v_sub.id, v_unit.unit_number, v_unit.u_title, v_unit.u_si, v_unit.u_ta)
        RETURNING id INTO v_unit_id;

        -- Insert subunits with trilingual titles
        INSERT INTO public.syllabus_subunits (unit_id, sub_number, title, sinhala_title, tamil_title, target_hours)
        SELECT 
          v_unit_id, 
          sub_lesson_code, 
          COALESCE(sub_lesson_title_en, sub_lesson_title),
          COALESCE(sub_lesson_title_si, sub_lesson_title),
          sub_lesson_title_ta,
          4
        FROM public.canonical_syllabus
        WHERE subject = v_canon_sub AND unit_number = v_unit.unit_number
        ORDER BY sub_lesson_code;
      END LOOP;
    END IF;
  END LOOP;
END;
$FUNC$;

-- 3. Seed any existing users automatically
DO $SEED$
DECLARE
  u RECORD;
BEGIN
  FOR u IN SELECT id FROM public.profiles LOOP
    PERFORM public.seed_user_syllabus_from_canonical(u.id);
  END LOOP;
END;
$SEED$;
